const state = Forge.require("echo.state");
Forge.onInteract(() => {
  const result = state.activate("A");
  if (result.newlyActivated) {
    Forge.self.setColor("#54f6bd");
    Forge.world.get("RelayStatusA")?.setColor("#54f6bd");
    Forge.vfx.restart("PulseA");
    Forge.audio.play("RelayBeep");
  }
  Forge.ui.setText("ObjectiveText",result.message);
  Forge.ui.setText("CounterText",result.count+" / 3 POWER NODES");
  if (result.complete) Forge.emit("echo.complete");
});

