let touched = false;
Forge.onTriggerEnter(() => {
 if (touched) return;
 touched = true;
 Forge.player.setCheckpoint("CheckpointPad");
 Forge.ui.setText("InfoText","CHECKPOINT SECURED • Respawn active");
 Forge.audio.play("RelayBeep");
 Forge.log("ECHO_CHECKPOINT");
});

let escaped=false;
Forge.onTriggerEnter(() => {
  const state=Forge.require("echo.state");
  if(escaped||state.count()!==3)return;
  escaped=true;
  Forge.ui.setText("ObjectiveText","MISSION COMPLETE • ECHO VAULT ESCAPED");
  Forge.ui.setText("InfoText","ALL SYSTEMS RESTORED • WELL PLAYED");
  Forge.vfx.restart("VaultVictoryVFX");
  Forge.log("ECHO_VAULT_WIN");
});

const active = new Set();
Forge.module({
 activate(id) {
   const before=active.size;
   active.add(id);
   const count=active.size;
   return {count,complete:count===3,newlyActivated:count>before,message:count===3?"VAULT UNLOCKED • REACH THE EXIT":"NODE "+id+" ONLINE • "+(3-count)+" REMAIN"};
 },
 count(){return active.size;}
});

let timer=0;
Forge.onStart(() => {
 Forge.ui.setText("ObjectiveText","INFILTRATE • ACTIVATE 3 POWER NODES");
 Forge.ui.setText("CounterText","0 / 3 POWER NODES");
 Forge.ui.setText("InfoText","Find the neon terminals • Press E to activate");
 Forge.log("ECHO_VAULT_READY");
});
Forge.onUpdate((dt)=> {
 timer+=dt;
 if(timer>.25){timer=0;Forge.ui.setText("HealthText","SHIELD "+Math.round(Forge.player.getHealth())+"/"+Math.round(Forge.player.getMaxHealth()));}
 const core=Forge.world.get("CoreBand");
 if(core) core.rotate(0,dt*14,0);
});
Forge.on("echo.complete",()=> {
 Forge.world.get("GateDoor")?.move(0,6,0);
 Forge.world.get("VaultCore")?.setColor("#55e3bc");
 Forge.ui.setText("ObjectiveText","VAULT OPEN • REACH THE SOUTH EXIT");
 Forge.ui.setText("InfoText","Head to the orange gate • Escape to win");
 Forge.vfx.restart("VaultVictoryVFX");
 Forge.audio.play("RelayBeep");
 Forge.log("ECHO_VAULT_UNLOCKED");
});

Forge.onClick(async () => {
 const count=Forge.require("echo.state").count();
 Forge.ui.setText("InfoText",count===3?"ESCAPE south through the opened gate":"Walk near the power nodes and press E • Avoid red barriers");
 await Forge.time.wait(3);
 Forge.ui.setText("InfoText",count===3?"Exit unlocked":"Keep moving • Use Shift to sprint");
});
